mapper.select:

SELECT COALESCE(MAX(attempt), 0)+1
FROM job_execution
WHERE job_name=#{name}
  AND business_date=#{date}


SELECT id
FROM job_execution
WHERE job_name=#{jobName}
  AND business_date=#{businessDate}
  AND data_scope=#{dataScope}
  AND status IN ('SUCCESS', 'SKIPPED')
  AND input_hash=#{inputHash}
ORDER BY id DESC
LIMIT 1

mapper.update:

UPDATE job_execution
SET
  status=#{status},
  ended_at=CURRENT_TIMESTAMP,
  error=#{error}
WHERE id=#{id}


UPDATE job_stage
SET
  status=#{status},
  ended_at=CURRENT_TIMESTAMP,
  error=#{error},
  data_status=#{dataStatus},
  details_json=#{detailsJson}
WHERE job_id=#{jobId}
  AND stage_name=#{stageName}
  AND status='RUNNING'

mapper.select:

SELECT id
FROM job_execution
WHERE job_name=#{name}
  AND business_date=#{date}
  AND data_scope=#{scope}
  AND status IN ('PENDING', 'RUNNING', 'CANCEL_REQUESTED', 'TIMEOUT_REQUESTED')
ORDER BY id DESC
LIMIT 1

mapper.update:

UPDATE job_execution
SET
  heartbeat_at=CURRENT_TIMESTAMP(6)
WHERE id=#{id}
  AND owner_id=#{owner}
  AND status IN ('RUNNING', 'CANCEL_REQUESTED', 'TIMEOUT_REQUESTED')
